using Microsoft.AspNetCore.DataProtection;
using Shop.Modules.Credit;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class CreditReminderPolicyTests
{
    private static CreditReminderPolicyInput Input()=>new(null,true,[-7,0,3],"09:30","Private schedule review",true);
    [Fact]public void NoCommercialCadenceIsInferredAndDisableHasNoHiddenSchedule(){CreditReminderPolicyRules.Validate(Input());CreditReminderPolicyRules.Validate(new(null,false,[],null,"Disable internal schedule",true));foreach(var x in new[]{Input()with{Confirmed=false},Input()with{DayOffsets=[]},Input()with{DayOffsets=[0,-1]},Input()with{DayOffsets=[0,0]},Input()with{DayOffsets=[-366]},Input()with{DayOffsets=[366]},Input()with{DayOffsets=Enumerable.Range(-16,32).ToArray()},Input()with{SendAt=null},Input()with{SendAt="9:30"},Input()with{SendAt="24:00"},Input()with{SendAt="۰۹:۳۰"},Input()with{Enabled=false},Input()with{Note=""},Input()with{Version="bad"}})Assert.Throws<BusinessException>(()=>CreditReminderPolicyRules.Validate(x));}
    [Theory][InlineData("2026-10-27T20:29:59Z",false)][InlineData("2026-10-27T20:30:00Z",true)][InlineData("2026-10-28T20:29:59Z",true)][InlineData("2026-10-28T20:30:00Z",false)]
    public void DueDayUsesTehranMidnightAndDoesNotCatchUpTomorrow(string now,bool expected){var p=Policy([0],"00:00");Assert.Equal(expected,CreditReminderPolicyRules.Due(p,"2026-10-28",DateTimeOffset.Parse(now)));}
    [Fact]public void OffsetsAndExplicitTimeAreEvaluatedAgainstActualDueDate(){var p=Policy([-3,0,2],"09:30");Assert.False(CreditReminderPolicyRules.Due(p,"2026-10-31",DateTimeOffset.Parse("2026-10-28T05:59:59Z")));Assert.True(CreditReminderPolicyRules.Due(p,"2026-10-31",DateTimeOffset.Parse("2026-10-28T06:00:00Z")));Assert.True(CreditReminderPolicyRules.Due(p,"2026-10-26",DateTimeOffset.Parse("2026-10-28T06:00:00Z")));Assert.False(CreditReminderPolicyRules.Due(p,"2026-10-27",DateTimeOffset.Parse("2026-10-28T06:00:00Z")));Assert.False(CreditReminderPolicyRules.Due(p with{Enabled=false},"2026-10-28",DateTimeOffset.Parse("2026-10-28T06:00:00Z")));Assert.False(CreditReminderPolicyRules.Due(p with{At=DateTimeOffset.Parse("2026-10-29T00:00:00Z")},"2026-10-28",DateTimeOffset.Parse("2026-10-28T06:00:00Z")));}
    private static CreditReminderPolicyRevisionData Policy(int[] days,string time)=>new(new string('a',32),1,"AAAAAAAAAAE=",true,days,time,"Private note",DateTimeOffset.Parse("2026-01-01T00:00:00Z"));
    [Fact]public void PolicyCiphertextIsBoundToActorPurposeAndRevisionOrCommand(){var p=new DataProtectionCreditReminderPolicyProtection(new EphemeralDataProtectionProvider());var actor=Guid.NewGuid().ToString();var id=new string('a',32);var data=p.Protect("revision",actor,id,"synthetic only");Assert.Equal("synthetic only",p.Unprotect("revision",actor.ToUpperInvariant(),id,data));Assert.Throws<BusinessException>(()=>p.Unprotect("receipt",actor,id,data));Assert.Throws<BusinessException>(()=>p.Unprotect("revision",Guid.NewGuid().ToString(),id,data));Assert.Throws<BusinessException>(()=>p.Unprotect("revision",actor,new string('b',32),data));Assert.Throws<BusinessException>(()=>p.Unprotect("revision",actor,id,[1,2,3]));}
}
